#!/usr/bin/env node
// E043 independent integer-only verifier. No Python, SciPy, NumPy or LP solver.
// Usage: node E043_verify_reproduced.js E043_REPRODUCED_0_300.json
// E036_WITNESSES.json is generated by E036_reproduce.py.
'use strict';
const fs=require('fs');
const W=JSON.parse(fs.readFileSync('E036_WITNESSES.json','utf8'));
const D=JSON.parse(fs.readFileSync(process.argv[2]||'E043_REPRODUCED_0_300.json','utf8'));
function check(q,m){if(!q)throw Error(m)}
check(W.length===156,'source witness count');
for(let i=0;i<W.length;i++){
 const S=W[i];
 for(let s=0;s<3;s++){
  for(let r=0;r<6;r++)check(S[s][r].length===10&&new Set(S[s][r]).size===10&&S[s][r].every(v=>Number.isInteger(v)&&v>=0&&v<10),'Latin row '+i);
  for(let c=0;c<10;c++)check(new Set(S[s].map(row=>row[c])).size===6,'Latin column '+i);
 }
 for(const [a,b] of [[0,1],[0,2],[1,2]]){
  const pairs=new Set();
  for(let r=0;r<6;r++)for(let c=0;c<10;c++)pairs.add(S[a][r][c]*10+S[b][r][c]);
  check(pairs.size===60,'six-row overlay '+i);
 }
}
let dual=0,zero=0,checkedCandidates=0;
for(const z of D.certificates){
 check(z.kind==='ZERO'||z.kind==='DUAL','unknown or incomplete case');
 const S=W[z.orbit].map(sq=>z.rows.map(r=>sq[r]));
 const pairs=[[0,1],[0,2],[1,2]],occ=[];
 for(const [a,b] of pairs){
  const set=new Set();
  for(let r=0;r<4;r++)for(let c=0;c<10;c++)set.add(S[a][r][c]*10+S[b][r][c]);
  check(set.size===40,'four-row overlay');occ.push(set);
 }
 const missing=[];
 for(let s=0;s<3;s++){
  const col=[];
  for(let c=0;c<10;c++){
   const used=new Set(S[s].map(row=>row[c]));
   check(used.size===4,'four-row column');
   col.push(Array.from({length:10},(_,i)=>i).filter(i=>!used.has(i)));
  }
  missing.push(col);
 }
 const E=[];
 for(let p=0;p<3;p++)for(let a=0;a<10;a++)for(let b=0;b<10;b++)
  if(!occ[p].has(a*10+b))E.push(['P',p,a,b]);
 for(let s=0;s<3;s++)for(let c=0;c<10;c++)for(const v of missing[s][c])E.push(['C',s,c,v]);
 check(E.length===360,'demand count');
 const keys=E.map(e=>e.join(':'));
 const weights=z.kind==='DUAL'?(z.weights||new Array(360).fill(-1)):null;
 if(weights&&z.delta)for(const [i,v] of z.delta)weights[i]+=v;
 check(!weights||weights.length===360,'dual length');
 const wm=new Map();
 if(weights)for(let i=0;i<360;i++)wm.set(keys[i],weights[i]);
 const target=z.kind==='ZERO'?z.demand.join(':'):null;
 if(target)check(wm.size===0&&keys.includes(target),'missing zero demand');
 let max=-Infinity,found=0,ncand=0;
 for(let c=0;c<10;c++)for(const a of missing[0][c])for(const b of missing[1][c])for(const d of missing[2][c]){
  if(occ[0].has(a*10+b)||occ[1].has(a*10+d)||occ[2].has(b*10+d))continue;
  ncand++;
  const six=[`P:0:${a}:${b}`,`P:1:${a}:${d}`,`P:2:${b}:${d}`,
             `C:0:${c}:${a}`,`C:1:${c}:${b}`,`C:2:${c}:${d}`];
  if(target&&six.includes(target))found++;
  if(weights){
   let v=0;for(const key of six){check(wm.has(key),'missing resource');v+=wm.get(key);}
   check(v<=0,'positive candidate dual');
   if(v>max)max=v;
  }
 }
 checkedCandidates+=ncand;
 if(weights){
  const rhs=weights.reduce((a,b)=>a+b,0);
  check(rhs>0&&rhs===(z.rhs??z.sum),'bad dual RHS');
  check(max===(z.maxscore??z.max),'bad dual max');
  dual++;
 }else{check(found===0,'false zero support');zero++;}
}
console.log(JSON.stringify({status:'PASS',range:[D.start,D.end],dual,zero,candidates:checkedCandidates}));
